mapper.select:
SELECT K.*, S.ShopName AS ShopName
FROM shopwizard.tOrdOrderKeywrd K
INNER JOIN shopwizard.tCmpShop S ON K.ShopCode = S.ShopCode

    AND K.KeywrdSeq = #{pKeywrdSeq}
    AND K.KeywrdName LIKE CONCAT('%',#{pKeywrdName},'%')
    AND K.ShopCode = #{pShopCode}
    AND K.KeywrdSect = #{pKeywrdSect}

LIMIT #{pPageOffset}, #{pPageSize}

SELECT COUNT(*)
FROM shopwizard.tOrdOrderKeywrd K
INNER JOIN shopwizard.tCmpShop S ON K.ShopCode = S.ShopCode

    AND K.KeywrdSeq = #{pKeywrdSeq}
    AND K.KeywrdName LIKE CONCAT('%',#{pKeywrdName},'%')
    AND K.ShopCode = #{pShopCode}
    AND K.KeywrdSect = #{pKeywrdSect}
